// SystemClock is the production Clock backed by time.Now.
type SystemClock struct{}

func (SystemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens per second),
// burst capacity, and clock. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available at the current time.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so. It never blocks.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if n tokens are available now. n <= 0 returns 0.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n <= 0 {
		return 0
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		return 0
	}
	need := float64(n) - l.tokens
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
