// NewLimiter creates a Limiter with the given burst capacity and refill rate
// (tokens per second), starting full. If clock is nil, the real clock is used.
func NewLimiter(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		clock:    clock,
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     rate,
		last:     clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// It consumes the tokens if allowed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
